import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.BZk_B2cc.js";const m=JSON.parse('{"title":"F5: Kinetic Mobile-First UI & Bottom Sheet Drawers","description":"","frontmatter":{},"headers":[],"relativePath":"features/F5-kinetic-bottom-sheets.md","filePath":"features/F5-kinetic-bottom-sheets.md"}'),o={name:"features/F5-kinetic-bottom-sheets.md"};function n(r,e,l,c,h,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="f5-kinetic-mobile-first-ui-bottom-sheet-drawers" tabindex="-1">F5: Kinetic Mobile-First UI &amp; Bottom Sheet Drawers <a class="header-anchor" href="#f5-kinetic-mobile-first-ui-bottom-sheet-drawers" aria-label="Permalink to &quot;F5: Kinetic Mobile-First UI &amp; Bottom Sheet Drawers&quot;">​</a></h1><h2 id="_1-description-animation-choreography" tabindex="-1">1. Description &amp; Animation Choreography <a class="header-anchor" href="#_1-description-animation-choreography" aria-label="Permalink to &quot;1. Description &amp; Animation Choreography&quot;">​</a></h2><p>The frontend is engineered as a mobile-first responsive web application. Panels for searching locations, choosing vehicle types, waiting for drivers, and accepting rides are rendered as layered bottom sheets animated using GreenSock (GSAP).</p><h2 id="_2-gsap-drawer-animation-flow" tabindex="-1">2. GSAP Drawer Animation Flow <a class="header-anchor" href="#_2-gsap-drawer-animation-flow" aria-label="Permalink to &quot;2. GSAP Drawer Animation Flow&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Trigger[User Action: Focus Input / Select Ride] --&gt; GSAPHook[useGSAP Hook Trigger]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GSAPHook --&gt; Tween[gsap.to panelRef { y: &#39;0%&#39;, duration: 0.5, ease: &#39;power2.out&#39; }]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tween --&gt; Viewport[Smooth Drawer Slide from Bottom]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Dismiss[User Dismisses Panel] --&gt; Reverse[gsap.to panelRef { y: &#39;100%&#39; }]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;For the client interface, I designed a mobile-first architecture utilizing GSAP to replicate the tactile feel of native mobile applications. Complex UI states—such as destination search suggestions, vehicle selection carousels, and driver acceptance popups—are managed as sliding bottom sheets. I used the <code>useGSAP</code> hook to animate CSS translation matrices with cubic power-easing curves, preventing layout thrashing and maintaining a rock-solid 60 frames per second. This gives web users the exact fluid feel of a native iOS or Android ride-hailing app.&quot;</p>`,7)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
